PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, project_type TEXT NOT NULL CHECK(project_type IN ('full_route','component','tool','research','official','candidate')), review_status TEXT NOT NULL CHECK(review_status IN ('pending_review','accepted','rejected')), ranking_eligible INTEGER NOT NULL CHECK(ranking_eligible IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE repositories (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), provider TEXT NOT NULL DEFAULT 'github', provider_repo_id TEXT NOT NULL, owner TEXT NOT NULL, name TEXT NOT NULL, canonical_url TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), UNIQUE(provider,provider_repo_id));
CREATE TABLE sources (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), adapter TEXT NOT NULL, enabled INTEGER NOT NULL, priority TEXT NOT NULL, canonical_url TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE source_state (source_id TEXT PRIMARY KEY REFERENCES sources(id), next_due_at TEXT NOT NULL, last_checked_at TEXT, last_success_at TEXT, failure_count INTEGER NOT NULL DEFAULT 0, last_error_code TEXT, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE INDEX idx_due ON source_state(next_due_at);
CREATE TABLE events (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), project_id TEXT REFERENCES projects(id), external_id TEXT NOT NULL, event_type TEXT NOT NULL, source_published_at TEXT, observed_at TEXT NOT NULL, content_hash TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), UNIQUE(source_id,external_id));
CREATE INDEX idx_events_project_date ON events(project_id,observed_at);
CREATE TABLE claims (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), event_id TEXT REFERENCES events(id), statement TEXT NOT NULL, target_version TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE evidence (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), project_id TEXT NOT NULL REFERENCES projects(id), level TEXT NOT NULL CHECK(level IN ('E0','E1','E2','E3')), target_version TEXT NOT NULL, content_hash TEXT NOT NULL, observed_at TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE claim_evidence (claim_id TEXT REFERENCES claims(id), evidence_id TEXT REFERENCES evidence(id), relation TEXT NOT NULL CHECK(relation IN ('supports','contradicts')), PRIMARY KEY(claim_id,evidence_id,relation));
CREATE TABLE rubrics (id TEXT PRIMARY KEY, version TEXT NOT NULL, definition_hash TEXT NOT NULL, rules_commit TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE milestones (rubric_id TEXT REFERENCES rubrics(id), milestone_id TEXT NOT NULL, weight INTEGER NOT NULL CHECK(weight>0), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(rubric_id,milestone_id));
CREATE TABLE assessments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), rubric_id TEXT NOT NULL, milestone_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('unassessed','claimed','in_review','confirmed','disputed','refuted','regressed','not_applicable')), target_version TEXT NOT NULL, reviewer TEXT NOT NULL, review_commit TEXT NOT NULL, effective_at TEXT NOT NULL, recorded_at TEXT NOT NULL, supersedes_id TEXT REFERENCES assessments(id), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), FOREIGN KEY(rubric_id,milestone_id) REFERENCES milestones(rubric_id,milestone_id));
CREATE INDEX idx_assessment_project_rubric_date ON assessments(project_id,rubric_id,milestone_id,effective_at);
CREATE TABLE assessment_evidence (assessment_id TEXT REFERENCES assessments(id), evidence_id TEXT REFERENCES evidence(id), relation TEXT CHECK(relation IN ('supports','contradicts')), PRIMARY KEY(assessment_id,evidence_id,relation));
CREATE TABLE score_history (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), rubric_id TEXT REFERENCES rubrics(id), score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), confirmed_count INTEGER NOT NULL CHECK(confirmed_count BETWEEN 0 AND 20), effective_at TEXT NOT NULL, recorded_at TEXT NOT NULL, cause_assessment_id TEXT REFERENCES assessments(id), input_hash TEXT NOT NULL, rules_commit TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), UNIQUE(project_id,rubric_id,input_hash));
CREATE INDEX idx_score_project_date ON score_history(project_id,rubric_id,effective_at);
CREATE TABLE project_relations (id TEXT PRIMARY KEY, from_project_id TEXT NOT NULL REFERENCES projects(id), to_project_id TEXT NOT NULL REFERENCES projects(id), relation_type TEXT NOT NULL, state TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), CHECK(from_project_id<>to_project_id));
CREATE TABLE discovery_candidates (id TEXT PRIMARY KEY, provider TEXT NOT NULL DEFAULT 'github', provider_repo_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending_review','accepted','rejected','duplicate','deferred')), first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, linked_project_id TEXT REFERENCES projects(id), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), UNIQUE(provider,provider_repo_id));
CREATE INDEX idx_candidates_status_date ON discovery_candidates(status,first_seen_at);
CREATE TABLE analysis_jobs (id TEXT PRIMARY KEY, input_hash TEXT NOT NULL, model_id TEXT NOT NULL, prompt_version TEXT NOT NULL, status TEXT NOT NULL, next_attempt_at TEXT, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), UNIQUE(input_hash,model_id,prompt_version));
CREATE INDEX idx_analysis_due ON analysis_jobs(status,next_attempt_at);
CREATE TABLE pipeline_runs (id TEXT PRIMARY KEY, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE usage_daily (date_utc TEXT NOT NULL, provider TEXT NOT NULL, metric TEXT NOT NULL, measured_value REAL, estimated_value REAL, observed_at TEXT NOT NULL, source TEXT NOT NULL, PRIMARY KEY(date_utc,provider,metric));
CREATE TABLE publications (id TEXT PRIMARY KEY, schema_version TEXT NOT NULL, generated_at TEXT NOT NULL, last_collection_success_at TEXT, source_run_id TEXT REFERENCES pipeline_runs(id), manifest_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('building','complete')), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE publication_blobs (publication_id TEXT REFERENCES publications(id), resource_key TEXT NOT NULL, body_json TEXT NOT NULL CHECK(json_valid(body_json)), body_hash TEXT NOT NULL, generated_at TEXT NOT NULL, PRIMARY KEY(publication_id,resource_key));
CREATE TABLE publication_pointer (name TEXT PRIMARY KEY CHECK(name='current'), publication_id TEXT NOT NULL REFERENCES publications(id), updated_at TEXT NOT NULL);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, reason TEXT NOT NULL, review_commit TEXT, occurred_at TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE pipeline_state (key TEXT PRIMARY KEY, value_json TEXT NOT NULL CHECK(json_valid(value_json)));
CREATE TRIGGER immutable_assessments BEFORE UPDATE ON assessments BEGIN SELECT RAISE(ABORT,'append-only assessment'); END;
CREATE TRIGGER immutable_rubric BEFORE UPDATE ON rubrics BEGIN SELECT RAISE(ABORT,'immutable rubric version'); END;
CREATE TRIGGER immutable_audit BEFORE UPDATE ON audit_log BEGIN SELECT RAISE(ABORT,'append-only audit'); END;
CREATE TRIGGER pointer_complete_insert BEFORE INSERT ON publication_pointer WHEN (SELECT status FROM publications WHERE id=NEW.publication_id)<>'complete' BEGIN SELECT RAISE(ABORT,'incomplete publication'); END;
CREATE TRIGGER pointer_complete_update BEFORE UPDATE ON publication_pointer WHEN (SELECT status FROM publications WHERE id=NEW.publication_id)<>'complete' BEGIN SELECT RAISE(ABORT,'incomplete publication'); END;
